#!/usr/bin/env node
// Bundle the existing VMS Plus helpers; do not fork their implementation.
const fs = require('node:fs');
const path = require('node:path');
const base = fs.readFileSync(path.join(__dirname, 'overhaul2-plugin/code.js'), 'utf8');
const marker = 'figma.ui.onmessage = async (msg) => {';
const at = base.lastIndexOf(marker);
if (at < 0) throw new Error('Missing original plugin dispatch boundary');
const screens = fs.readFileSync(path.join(__dirname, 'sp09-plugin/screens.js'), 'utf8');
fs.writeFileSync(path.join(__dirname, 'sp09-plugin/code.js'),
  '// GENERATED by node figma-export/build-sp09-plugin.js; edit screens.js or shared Overhaul helpers.\n' + base.slice(0, at) + '\n' + screens);
console.log('Built sp09-plugin/code.js');
